const QA_NAMES = ['Alex', 'Samira', 'Theo', 'Lena', 'Marcus', 'Nina', 'Elliot', 'Rosa', 'Dev', 'Camille', 'Owen', 'Tasha', 'Ben', 'Maya', 'Luis', 'Sophie', 'Andre', 'Keiko', 'Noah', 'Imani', 'Gabe', 'Leah', 'Jonah', 'Asha', 'Miles', 'Carmen'];
const QA_LOCATIONS = ['St. Johns', 'Woodstock', 'Laurelhurst', 'Montavilla', 'Overlook', 'Richmond', 'Cully', 'Boise', 'Sunnyside', 'Arbor Lodge', 'Concordia', 'Brooklyn', 'Hawthorne'];
const QA_DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
const QA_EXPERIENCE = ['Puppy care', 'Senior dog care', 'Medication / pills', 'Injections / shots', 'Special diets', 'Mobility assistance', 'Separation anxiety', 'Behavioral needs'];
const QA_VISIT_TYPES = ['Walks', 'Drop-in visits', 'Daycare', 'Sleepovers', 'House sitting'];
const QA_IMAGES = [jordanImage, priyaImage, mikeImage, peopleImage];
const QA_PET_IMAGES = [zukiImage, mochiImage, zukiWalkImage];
const generatedProfiles = QA_NAMES.map((firstName, index) => {
  const role = index % 2 === 0 ? 'bonus' : 'owner';
  const distance = 1 + ((index * 7) % 89);
  const day = QA_DAYS[index % QA_DAYS.length];
  const secondDay = QA_DAYS[(index + 2) % QA_DAYS.length];
  const homeType = index % 3 === 0 ? 'Apartment' : 'House';
  const hasYard = homeType === 'House' && index % 4 !== 0;
  const petName = ['Pepper', 'Scout', 'Winnie', 'Otis', 'Clover', 'Bean', 'Poppy', 'Louie', 'Nori', 'Archie', 'Daisy', 'Finn', 'Ruby'][index % 13];
  const name = role === 'owner' ? `${firstName} + ${petName}` : firstName;
  const image = QA_IMAGES[index % QA_IMAGES.length];
  const experience = [QA_EXPERIENCE[index % QA_EXPERIENCE.length], QA_EXPERIENCE[(index + 3) % QA_EXPERIENCE.length]];
  const schedule = [`${day} ${index % 2 ? 'PM' : 'AM'}`, `${secondDay} ${index % 3 ? 'PM' : 'AM'}`];
  return {
    id: `qa-${role}-${index + 1}`, role, type: role === 'owner' ? 'PET OWNER' : 'BONUS HUMAN', name, humanName: firstName,
    location: `${QA_LOCATIONS[index % QA_LOCATIONS.length]} · ${distance} mi`, distance, image, photos: [image],
    ...(role === 'owner' ? { pet: { name: petName, photos: [QA_PET_IMAGES[index % QA_PET_IMAGES.length]], summary: `${petName} is an affectionate adult dog who enjoys familiar people and predictable routines.`, meta: `${2 + (index % 12)} years old · Mixed breed` } } : {}),
    intro: role === 'owner' ? `${firstName} is looking for one dependable person to build a lasting bond with ${petName}.` : `${firstName} misses everyday dog companionship and hopes to become a familiar, trusted person nearby.`,
    looking: index % 2 ? 'A steady weekly rhythm with clear communication and time to build trust.' : 'A long-term connection with relaxed visits, walks, and occasional weekends.',
    highlights: [experience[0], hasYard ? 'Yard' : 'No yard', schedule[0]], informational: [homeType, index % 2 ? 'Calm household' : 'Flexible routine'],
    attributes: { Location: [`${distance} miles away`, QA_LOCATIONS[index % QA_LOCATIONS.length]], Availability: schedule, Experience: experience, 'Home environment': [homeType, hasYard ? 'Yard' : 'No yard'] },
    filterData: { schedule, experience, visitTypes: [QA_VISIT_TYPES[index % QA_VISIT_TYPES.length], QA_VISIT_TYPES[(index + 2) % QA_VISIT_TYPES.length]], home: { homeType, hasYard, dogs: index % 5 === 0 ? 'Has dogs' : 'No dogs', cats: index % 4 === 0 ? 'Has cats' : 'No cats' } },
    facts: role === 'owner' ? [['About us', `${firstName} and ${petName} value calm routines and reliable communication.`], ['Why a bonus human', `A familiar local person would give ${petName} another meaningful relationship.`], ['Ideal arrangement', 'One recurring visit most weeks, with flexibility as trust grows.']] : [['Our pet experience', `Experience includes ${experience.join(' and ').toLowerCase()}.`], ['Why this connection', 'A lasting bond feels more meaningful than occasional transactional care.'], ['Availability', schedule.join(' and ')]],
    prompts: [['A good visit', 'A relaxed walk, a familiar routine, and an honest update.'], ['Green flag', 'Clear expectations and a pet-first pace.']],
  };
});
