function Button({ label, onPress, tone = 'primary', small = false, disabled = false }) {
  return <Pressable accessibilityRole="button" disabled={disabled} onPress={onPress} style={({ pressed }) => [styles.button, styles[`button_${tone}`], small && styles.buttonSmall, pressed && !disabled && { opacity: .76 }, disabled && { opacity: .45 }]}>
    <Text style={[styles.buttonText, styles[`buttonText_${tone}`]]}>{label}</Text>
  </Pressable>;
}

function Pill({ children, warm = false }) { return <View style={[styles.pill, warm && styles.pillWarm]}><Text style={[styles.pillText, warm && { color: C.clay }]}>{children}</Text></View>; }
function SectionTitle({ eyebrow, title, right }) { return <View style={styles.sectionTitle}><View style={styles.sectionTitleCopy}><Text style={styles.eyebrow}>{eyebrow}</Text><Text style={styles.h2}>{title}</Text></View>{right}</View>; }
function StatusLabel({ children, tone = 'neutral' }) { return <View style={[styles.statusLabel, styles[`statusLabel_${tone}`]]}><Text style={[styles.statusLabelText, styles[`statusLabelText_${tone}`]]}>{children}</Text></View>; }
function BrandWordmark() {
  if (Platform.OS !== 'web') return <Text style={styles.wordmark}>bonus human</Text>;
  return <View style={styles.webWordmarkRow}><Text style={styles.wordmark}>bonus human</Text><Text style={styles.webPrototypeLabel}>INTERACTIVE PROTOTYPE</Text></View>;
}
function Subtabs({ items, value, onChange, accessibilityPrefix = '' }) { return <View style={styles.subtabs}>{items.map(([id, label]) => <Pressable accessibilityRole="button" accessibilityLabel={`${label}${accessibilityPrefix ? ` ${accessibilityPrefix}` : ''} tab`} key={id} onPress={() => onChange(id)} style={[styles.subtab, value === id && styles.subtabActive]}><Text style={[styles.subtabText, value === id && styles.subtabTextActive]}>{label}</Text></Pressable>)}</View>; }
function ConnectAction({ state, onPress }) {
  const connected = state === 'connected'; const pending = state === 'requested';
  return <Pressable accessibilityRole="button" accessibilityLabel={connected ? "You're connected" : pending ? 'Undo request' : 'Connect'} onPress={onPress} style={({ pressed }) => [styles.connectButton, (connected || pending) && styles.connectButtonSent, pressed && styles.connectButtonPressed]}><Ionicons name={connected ? 'people' : pending ? 'checkmark-circle' : 'link'} size={19} color={C.white} /><Text style={styles.connectButtonText}>{connected ? "You're connected" : pending ? 'Request sent' : 'Connect'}</Text></Pressable>;
}

function DecisionActions({ state, onConnect, onNotNow, onOpenConnection }) {
  if (state === 'connected') return <View style={styles.stickyDecisionInner}><ConnectAction state="connected" onPress={onOpenConnection} /><Button tone="light" label="Open Connection" onPress={onOpenConnection} /></View>;
  if (state === 'requested') return <View style={styles.stickyDecisionInner}><View style={styles.interestSentState}><Ionicons name="checkmark-circle" size={18} color={C.sage} /><Text style={styles.interestSentText}>Request sent</Text></View><Button tone="light" label="Undo request" onPress={onConnect} /></View>;
  if (state === 'passed') return <View style={styles.stickyDecisionInner}><View style={styles.interestSentState}><Ionicons name="checkmark-circle" size={18} color={C.sage} /><Text style={styles.interestSentText}>Not now</Text></View><Button tone="light" label="Undo" onPress={onNotNow} /></View>;
  return <View style={styles.stickyDecisionInner}><Button tone="light" label="Not now" onPress={onNotNow} /><ConnectAction state={null} onPress={onConnect} /></View>;
}

function TopBar({ title = 'bonus human', back, onBack, onAccount, action }) {
  return <View style={styles.topBar}>
    {back ? <Pressable accessibilityLabel="Go back" onPress={onBack} hitSlop={12}><Text style={styles.back}>‹</Text></Pressable> : <View style={styles.brandMark}><Text style={styles.brandMarkText}>B</Text></View>}
    <Text style={styles.topTitle}>{title}</Text>
    <View style={styles.topAction}>{action || (onAccount ? <Pressable accessibilityLabel="Open account" onPress={onAccount} style={styles.avatarMini}><Text style={styles.avatarMiniText}>M</Text></Pressable> : null)}</View>
  </View>;
}

function PhotoGallery({ photos, style, accessibilityLabel }) {
  const [photoIndex, setPhotoIndex] = useState(0);
  const move = () => setPhotoIndex((photoIndex + 1) % photos.length);
  return <View accessibilityLabel={accessibilityLabel} style={styles.gallery}>
    <Pressable accessibilityRole="button" accessibilityLabel="Next photo" onPress={move}><Image source={photos[photoIndex]} style={style} /></Pressable>
    {photos.length > 1 && <View accessibilityLabel={`Photo ${photoIndex + 1} of ${photos.length}`} style={styles.galleryPosition}>{photos.map((_, i) => <View key={i} style={[styles.galleryDot, i === photoIndex && styles.galleryDotActive]} />)}</View>}
  </View>;
}

function FilterChip({ label, accessibilityLabel, selected, onPress }) {
  return <Pressable accessibilityRole="button" accessibilityLabel={accessibilityLabel || label} accessibilityState={{ selected }} onPress={onPress} style={[styles.filterChip, selected && styles.filterChipActive]}><Text style={[styles.filterChipText, selected && styles.filterChipTextActive]}>{label}</Text></Pressable>;
}

const DEFAULT_HOME_FILTER = { homeType: 'Any', hasYard: false, dogs: 'Any', cats: 'Any' };
const DEFAULT_FILTERS = { radius: 10, schedule: [], experience: [], visitTypes: [], home: DEFAULT_HOME_FILTER };
const DAYS = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
